import { useState } from 'react';
import {
  JxScreen,
  JxHeader,
  JxBadge,
  JxSegmentedControl,
  JxSegmentedItem,
  JxFormRow,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSection,
  JxSelect,
  JxSelectOption,
  JxStack,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type FontFamily = 'system' | 'serif' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  compact: boolean;
  font: FontFamily;
}

interface AppearanceSettingsScreenProps {
  initialTheme?: Theme;
  initialScale?: number;
  initialCompact?: boolean;
  initialFont?: FontFamily;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({
  initialTheme = 'system',
  initialScale = 100,
  initialCompact = false,
  initialFont = 'system',
  onChange,
}: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<Theme>(initialTheme);
  const [scale, setScale] = useState<number>(initialScale);
  const [compact, setCompact] = useState<boolean>(initialCompact);
  const [font, setFont] = useState<FontFamily>(initialFont);

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({
      theme,
      scale,
      compact,
      font,
      ...next,
    });
  };

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleCompactChange = (value: boolean) => {
    setCompact(value);
    emit({ compact: value });
  };

  const handleFontChange = (value: FontFamily) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <JxScreen>
      <JxHeader
        title="Внешний вид"
        actions={<JxBadge tone="neutral">{THEME_LABELS[theme]}</JxBadge>}
      />

      <JxStack direction="column" gap="var(--jx-space-lg)">
        <JxFormRow label="Тема">
          <JxSegmentedControl
            value={theme}
            onChange={(value) => handleThemeChange(value as Theme)}
          >
            <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
            <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
            <JxSegmentedItem value="system">Системная</JxSegmentedItem>
          </JxSegmentedControl>
        </JxFormRow>

        <JxFormRow
          label="Масштаб интерфейса"
          description={`${scale}%`}
        >
          <JxSlider
            min={80}
            max={140}
            step={5}
            value={scale}
            onChange={(value) => handleScaleChange(value as number)}
            aria-label="Масштаб интерфейса"
          />
        </JxFormRow>

        <JxFormRow label="Плотная вёрстка" description="Уменьшает отступы и высоту элементов">
          <JxSwitch
            checked={compact}
            onChange={(checked) => handleCompactChange(checked)}
            aria-label="Плотная вёрстка"
          />
        </JxFormRow>

        <JxDivider />

        <JxSection title="Ещё">
          <JxFormRow label="Шрифт">
            <JxSelect
              value={font}
              onChange={(value) => handleFontChange(value as FontFamily)}
            >
              <JxSelectOption value="system">Системный</JxSelectOption>
              <JxSelectOption value="serif">С засечками</JxSelectOption>
              <JxSelectOption value="mono">Моноширинный</JxSelectOption>
            </JxSelect>
          </JxFormRow>
        </JxSection>
      </JxStack>
    </JxScreen>
  );
}

